from __future__ import annotations

import base64
import json
import subprocess

import pytest

from raypack.core import compress_archive, extract_archive, verify_archive
from raypack.media import doctor_report

# Synthetic 160x90 MPEG-4/MP4 test fixture generated from FFmpeg testsrc.
# It is test data only; no third-party media content is embedded.
_FIXTURE = ""


def test_bundled_smart_video_round_trip(tmp_path):
    doctor = doctor_report()
    if not (doctor["video_ffmpeg"] and doctor["video_ffprobe"] and doctor["video_smart_encoder"]):
        pytest.skip("Smart video runtime unavailable")
    source = tmp_path / "fixture.mp4"
    source.write_bytes(base64.b64decode(_FIXTURE))
    archive = tmp_path / "fixture.rayz"
    compress_archive([source], archive, format="rayz", profile="smart")
    result = verify_archive(archive)
    assert result["ok"]
    assert result["smart_media"], "Smart MP4 fixture unexpectedly fell back to Exact"
    out = tmp_path / "out"
    extract_archive(archive, out)
    restored = out / "fixture.mp4"
    cp = subprocess.run([doctor["video_ffprobe"], "-v", "error", "-select_streams", "v:0", "-show_entries", "stream=width,height", "-of", "json", str(restored)], check=True, capture_output=True, text=True)
    stream = json.loads(cp.stdout)["streams"][0]
    assert (stream["width"], stream["height"]) == (160, 90)
